        pSprite = (BattleFxSummonTitanScatterSprite *)BATTLE_NEW_TASK_SLOT(BattleFx_SummonTitanBillboardSpriteTask);
        radius = rand() % 0x5DC + 0x1F4;
        angle = rand() & 0xFFF;
