/*
 * Updates bouncing trajectory and rendering for Titan rock debris.
 */
// FUNCTION: FF7 0x0059f707
void __cdecl BattleFx_SummonTitanBouncingDebrisTask(void)
{
    BattleFxScaleHistoryRing *scaleHistoryPtr;
    int frameCount;
    BattleFxTitanDebris *task;
    struct BattleFxShardTransformBatch *matrix;
    BattleFxEulerAngles16 *rotation;

    task = (BattleFxTitanDebris *)BATTLE_CURRENT_TASK_SLOT;
    rotation = (BattleFxEulerAngles16 *)Gfx_GetPsxScratchpadPtr(0);
    matrix = (struct BattleFxShardTransformBatch *)((int)rotation + 8);
    scaleHistoryPtr = (BattleFxScaleHistoryRing *)((char *)matrix + 0x1E);
    if (g_BattleIsPaused == 0) {
        task->angleX += task->spinX;
        task->angleY += task->spinY;
        task->angleZ += task->spinZ;
        task->posX += task->velX;
        task->posY += task->velY;
        if (task->posY > 0) {
            task->posY = -task->posY;
            task->velY = -task->velY >> 2;
        }
        task->velY += 0x14;
    }
    frameCount = task->frame;
    if (frameCount < 0xA) {
        g_BattleSummonTitanSpriteReq1.flags = 0x80;
        g_BattleSummonTitanSpriteReq1.progress = 0;
        Gfx_SetPsxPrimQuadState(9, 4, (GfxPsxSpriteQuadState *)Battle3d_GetOffscreenRenderObject(g_BattleSummonTitanCameraTrackTerm1));
        Gfx_SetPsxPrimQuadState(0xB, 4, (GfxPsxSpriteQuadState *)Battle3d_GetOffscreenRenderObject(g_BattleSummonTitanCameraTrackTerm2));
    } else {
        frameCount -= 0xA;
        if (frameCount < 5) {
            g_BattleSummonTitanSpriteReq1.flags = 0x88;
            g_BattleSummonTitanSpriteReq1.progress = (frameCount << 0xB) / 5 + 0x800;
            Gfx_SetPsxPrimQuadState(9, 1, (GfxPsxSpriteQuadState *)Battle3d_GetOffscreenRenderObject(g_BattleSummonTitanCameraTrackTerm3));
            Gfx_SetPsxPrimQuadState(0xB, 1, (GfxPsxSpriteQuadState *)Battle3d_GetOffscreenRenderObject(g_BattleSummonTitanCameraTrackTerm4));
        } else {
            task->ownerSlot = BATTLE_TASK_FREE;
            return;
        }
    }
    rotation->angleX = *(unsigned char *)&task->angleX << 4;
    rotation->angleY = *(unsigned char *)&task->angleY << 4;
    rotation->angleZ = *(unsigned char *)&task->angleZ << 4;
    RotMatrix((SVECTOR *)rotation, matrix);
    scaleHistoryPtr->historyNewest = task->historyNewest;
    scaleHistoryPtr->historyMiddle = scaleHistoryPtr->historyNewest;
    scaleHistoryPtr->historyOldest = scaleHistoryPtr->historyMiddle;
    ScaleMatrix(matrix, scaleHistoryPtr);
    matrix->posX = task->posX;
    matrix->posY = task->posY;
    matrix->posZ = task->posZ;
    MultiplyMatrix(&g_BattleCameraTransform, matrix, matrix);
    SetRotMatrix(matrix);
    SetTransMatrix(matrix);
    SetDrawColorRGB(0, 0, 0);
    RefreshGlobalTransformState();
    g_BattleOverlayDrawListHead = BattleFx_SummonTitanDrawPsxMesh((BattleFxTitanMeshInstance *)&g_BattleSummonTitanSpriteReq1, g_BattleCurrentOrderingTable + BATTLE_OT_DEPTH_SORTED, 0xC, g_BattleOverlayDrawListHead);
    if (g_BattleIsPaused == 0) {
        (task->frame)++;
    }
}

